import { field, select, checkbox, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid"><div class="field"><label for="pwaFile">Upload an app icon (PNG, square recommended)</label><input type="file" id="pwaFile" accept="image/png,image/jpeg,image/webp,image/svg+xml"><small>Recommended: 512x512 or larger square PNG.</small></div>${field({ id: "pwaBg", label: "Background color", type: "color", value: "#ffffff", help: "Fills the safe zone when icon is smaller than the export size." })}</div><div class="field-grid">${field({ id: "pwaPadding", label: "Safe-zone padding (%)", type: "number", value: "15", help: "Percentage of the icon that should stay inside the safe zone. Standard PWA maskable safe zone requires 40% padding (80% visible area)." })}${select({ id: "pwaExport", label: "Export reference size", options: [{label:"192x192 (minimum)",value:"192"},{label:"512x512 (recommended)",value:"512"},{label:"Both 192 and 512",value:"both"}], value: "both" })}</div><canvas id="pwaCanvas" width="512" height="512" style="display:none; max-width:256px; margin: 12px auto; border-radius: 12px; box-shadow: 0 2px 12px rgba(0,0,0,0.15);" aria-label="Icon safe zone preview"></canvas>`,async generate(root) {const fileInput = root.querySelector("#pwaFile");const bgColor = root.querySelector("#pwaBg").value;const paddingPct = parseInt(root.querySelector("#pwaPadding").value) || 15;const exportSize = root.querySelector("#pwaExport").value;const canvas = root.querySelector("#pwaCanvas");if (!fileInput.files.length) {canvas.style.display = "none";return {output: "Upload a square PNG icon (512x512 or larger recommended) to preview the PWA maskable safe zone and generate manifest icon entries.",preview: ""};}const file = fileInput.files[0];if (!file.type.startsWith("image/")) {return { output: "The selected file is not a supported image format. Upload a PNG, JPEG, WebP, or SVG icon." };}const img = await new Promise((resolve, reject) => {const reader = new FileReader();reader.onload = () => {const i = new Image();i.onload = () => resolve(i);i.onerror = reject;i.src = reader.result;};reader.onerror = reject;reader.readAsDataURL(file);});const size = 512;canvas.width = size;canvas.height = size;const ctx = canvas.getContext("2d");ctx.fillStyle = bgColor;ctx.fillRect(0, 0, size, size);const scale = Math.min(size / img.width, size / img.height);const iw = img.width * scale;const ih = img.height * scale;const ix = (size - iw) / 2;const iy = (size - ih) / 2;ctx.drawImage(img, ix, iy, iw, ih);const safeRadius = (size / 2) * (1 - paddingPct / 100);ctx.beginPath();ctx.arc(size / 2, size / 2, safeRadius, 0, Math.PI * 2);ctx.setLineDash([6, 4]);ctx.strokeStyle = "rgba(255, 255, 255, 0.9)";ctx.lineWidth = 3;ctx.stroke();ctx.beginPath();ctx.arc(size / 2, size / 2, safeRadius, 0, Math.PI * 2);ctx.setLineDash([6, 4]);ctx.strokeStyle = "rgba(0, 0, 0, 0.4)";ctx.lineWidth = 1;ctx.stroke();ctx.setLineDash([]);ctx.fillStyle = "rgba(255, 255, 255, 0.9)";ctx.font = "bold 16px system-ui, sans-serif";ctx.textAlign = "center";ctx.fillText("Safe zone", size / 2, size / 2 - safeRadius - 10);ctx.fillStyle = "rgba(0, 0, 0, 0.5)";ctx.fillText("Safe zone", size / 2 + 1, size / 2 - safeRadius - 9);canvas.style.display = "block";const previewHtml = `<div style="text-align:center"><p style="margin:0 0 8px;font-size:14px;color:var(--text-secondary)">The dashed circle shows the ${paddingPct}% safe-zone boundary. Keep important content inside it.</p></div>`;const iconEntries = [];if (exportSize === "192" || exportSize === "both") {iconEntries.push(`{ "src": "/icons/icon-192x192.png", "sizes": "192x192", "type": "image/png", "purpose": "any maskable" }`);}if (exportSize === "512" || exportSize === "both") {iconEntries.push(`{ "src": "/icons/icon-512x512.png", "sizes": "512x512", "type": "image/png", "purpose": "any maskable" }`);}return {output: [`/* PWA Maskable Icon — Safe Zone: ${paddingPct}% padding */`,`/* Background: ${bgColor} */`,`/* Source: ${file.name} (${img.width}x${img.height}) */`,``,`/* Manifest icon entries: */`,...iconEntries,``,`/* Notes */`,`/* 1. The safe zone is the inner 80% of the icon (${paddingPct}% padding on each side). */`,`/* 2. Set "purpose": "maskable" on icons that should adapt to platform shapes. */`,`/* 3. Export icons at 192x192 (minimum) and 512x512 (recommended) on your ${bgColor} background. */`,`/* 4. Icon must be a square PNG for best results. */`,`/* 5. Test with Lighthouse PWA audit and on an actual Android device. */`].join("\n"),preview: previewHtml};}};